import 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:get_it/get_it.dart';\n\nimport '../services/speech_to_text_service.dart';\nimport '../services/translation_service.dart';\n\n/// Provider para SpeechToTextService\nfinal speechToTextServiceProvider = Provider<SpeechToTextService>((ref) {\n  return GetIt.instance<SpeechToTextService>();\n});\n\n/// Provider para TranslationService\nfinal translationServiceProvider = Provider<TranslationService>((ref) {\n  return GetIt.instance<TranslationService>();\n});\n\n/// Estado de traducción actual\nclass TranslationState {\n  final String targetLanguage;\n  final Map<int, String> translations; // line index → traducción\n  final bool isLoading;\n  final String? error;\n  \n  const TranslationState({\n    this.targetLanguage = 'es',\n    this.translations = const {},\n    this.isLoading = false,\n    this.error,\n  });\n  \n  TranslationState copyWith({\n    String? targetLanguage,\n    Map<int, String>? translations,\n    bool? isLoading,\n    String? error,\n  }) {\n    return TranslationState(\n      targetLanguage: targetLanguage ?? this.targetLanguage,\n      translations: translations ?? this.translations,\n      isLoading: isLoading ?? this.isLoading,\n      error: error ?? this.error,\n    );\n  }\n}\n\n/// Provider de estado de traducción\nfinal translationProvider = StateNotifierProvider<TranslationNotifier, TranslationState>((ref) {\n  return TranslationNotifier();\n});\n\n/// Notifier para traducciones\nclass TranslationNotifier extends StateNotifier<TranslationState> {\n  TranslationNotifier() : super(const TranslationState());\n  \n  /// Traducir líneas de letras\n  Future<void> translateLines({\n    required List<String> lines,\n    required String targetLanguage,\n    String? sourceLanguage,\n  }) async {\n    state = state.copyWith(isLoading: true, error: null);\n    \n    try {\n      final translationService = GetIt.instance<TranslationService>();\n      final translatedLines = await translationService.translateLyrics(\n        lines: lines,\n        targetLang: targetLanguage,\n        sourceLang: sourceLanguage,\n      );\n      \n      // Crear mapa de traducciones\n      final translations = <int, String>{};\n      for (int i = 0; i < lines.length; i++) {\n        if (i < translatedLines.length) {\n          translations[i] = translatedLines[i];\n        }\n      }\n      \n      state = state.copyWith(\n        isLoading: false,\n        targetLanguage: targetLanguage,\n        translations: translations,\n      );\n    } catch (e) {\n      state = state.copyWith(\n        isLoading: false,\n        error: 'Error en traducción: $e',\n      );\n    }\n  }\n  \n  /// Cambiar idioma destino\n  void setTargetLanguage(String language) {\n    state = state.copyWith(targetLanguage: language);\n  }\n  \n  /// Limpiar traducciones\n  void clearTranslations() {\n    state = state.copyWith(translations: const {});\n  }\n}\n\n/// Estado de transcripción\nclass TranscriptionState {\n  final String transcription;\n  final bool isLoading;\n  final String? error;\n  final double progress;\n  \n  const TranscriptionState({\n    this.transcription = '',\n    this.isLoading = false,\n    this.error,\n    this.progress = 0.0,\n  });\n  \n  bool get hasTranscription => transcription.isNotEmpty;\n  bool get hasError => error != null;\n  \n  TranscriptionState copyWith({\n    String? transcription,\n    bool? isLoading,\n    String? error,\n    double? progress,\n  }) {\n    return TranscriptionState(\n      transcription: transcription ?? this.transcription,\n      isLoading: isLoading ?? this.isLoading,\n      error: error ?? this.error,\n      progress: progress ?? this.progress,\n    );\n  }\n}\n\n/// Provider de estado de transcripción\nfinal transcriptionProvider = StateNotifierProvider<TranscriptionNotifier, TranscriptionState>((ref) {\n  return TranscriptionNotifier();\n});\n\n/// Notifier para transcripción\nclass TranscriptionNotifier extends StateNotifier<TranscriptionState> {\n  TranscriptionNotifier() : super(const TranscriptionState());\n  \n  /// Transcribir audio\n  Future<void> transcribeAudio({\n    required List<int> audioBytes,\n    String? languageCode,\n  }) async {\n    state = state.copyWith(isLoading: true, error: null, progress: 0.1);\n    \n    try {\n      final speechService = GetIt.instance<SpeechToTextService>();\n      \n      // Detectar idioma si no se especifica\n      final detectedLanguage = languageCode ?? \n          await speechService.detectLanguage(audioBytes);\n      \n      state = state.copyWith(progress: 0.3);\n      \n      // Transcribir\n      final transcription = await speechService.transcribeAudio(\n        audioBytes: audioBytes,\n        languageCode: detectedLanguage,\n      );\n      \n      state = state.copyWith(\n        isLoading: false,\n        transcription: transcription,\n        progress: 1.0,\n      );\n    } catch (e) {\n      state = state.copyWith(\n        isLoading: false,\n        error: 'Error en transcripción: $e',\n      );\n    }\n  }\n  \n  /// Limpiar transcripción\n  void clearTranscription() {\n    state = const TranscriptionState();\n  }\n}\n